        if all(v == bg for v in grid[r]):
            r += 1
            continue
        a = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((a, r))
    if len(bands) < 2:
        return out
    a, ae = bands[0]
    b, be = bands[-1]
    if ae - a != be - b:
        return out
    n = ae - a

    # Find the horizontal registration shared by the two corresponding bands.
    shifts = []
    for d in range(-w + 1, w):
        same = total = 0
        for k in range(n):
            for c in range(w):
                q = c + d
                if 0 <= q < w:
                    same += (grid[a+k][c] != bg) == (grid[b+k][q] != bg)
                    total += 1
        shifts.append((same / total if total else 0, -abs(d), d))
    shift = max(shifts)[2]

    # Choose the most nearly matching row pair, then complete its missing
    # foreground cells on the less complete side using color 1.
    best = None
    for k in range(n):
        upper, lower = grid[a+k], grid[b+k]
        matches = union = 0
        miss_lower = []
        miss_upper = []
        for c in range(w):
            q = c + shift
            if not 0 <= q < w:
                continue
            x, y = upper[c] != bg, lower[q] != bg
            matches += x and y
            union += x or y
            if x and not y:
                miss_lower.append(q)
            elif y and not x:
                miss_upper.append(c)
        score = matches / union if union else 1.0
        candidate = (score, -len(miss_lower)-len(miss_upper), -k, k, miss_lower, miss_upper)
        if best is None or candidate > best:
            best = candidate
    if best is None:
        return out
    _, _, _, k, miss_lower, miss_upper = best
    # Only mark the one-sided additions beyond the current right edge of the
    # corresponding less-complete row; this is the demonstrated continuation.
    upper, lower = grid[a+k], grid[b+k]
    if len(miss_lower) and len(miss_lower) <= len(miss_upper):
        edge = max((c for c,v in enumerate(lower) if v != bg), default=-1)
        for c in miss_lower:
